    }

    static BigDecimal calcularValorParcelaCartao(BigDecimal totalFinal, int nParcelas) {
        if (nParcelas <= 3) {
            return totalFinal.divide(BigDecimal.valueOf(nParcelas), 10, java.math.RoundingMode.HALF_EVEN).setScale(2, java.math.RoundingMode.HALF_EVEN);
        }

        BigDecimal taxaMensal = BigDecimal.valueOf(0.0199);
        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);
