1	package com.loja.checkout.calculo.pagamento;
2	
3	import com.loja.checkout.util.Arredondador;
4	import java.math.BigDecimal;
5	
6	public class PagamentoCartao implements PagamentoCalculador {
7	    private int parcelas;
8	    private BigDecimal totalPedidoArmazenado;
9	
10	    public PagamentoCartao(int parcelas) {
11	        this.parcelas = parcelas;
12	    }
13	
14	    @Override
15	    public BigDecimal calcularAjuste(BigDecimal totalPedido) {
16	        this.totalPedidoArmazenado = totalPedido;
17	
18	        if (parcelas <= 3) {
19	            return Arredondador.arredondar(BigDecimal.ZERO);
20	        }
21	
22	        BigDecimal taxaMensal = BigDecimal.valueOf(0.0199);
23	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);
24	        BigDecimal umMaisTaxaElevado = umMaisTaxa.pow(parcelas);
25	
26	        BigDecimal denominador = umMaisTaxaElevado.subtract(BigDecimal.ONE);
27	        BigDecimal numerador = totalPedido.multiply(taxaMensal).multiply(umMaisTaxaElevado);
28	
29	        BigDecimal parcela = numerador.divide(denominador, 10, java.math.RoundingMode.HALF_EVEN);
30	        parcela = Arredondador.arredondar(parcela);
31	
32	        BigDecimal totalComJuros = parcela.multiply(BigDecimal.valueOf(parcelas));
33	        return totalComJuros.subtract(totalPedido);
34	    }
35	
36	    @Override
37	    public BigDecimal calcularValorParcela(BigDecimal totalFinal, int nParcelas) {
38	        if (nParcelas <= 3) {
39	            return Arredondador.arredondar(totalFinal.divide(BigDecimal.valueOf(nParcelas), 10, java.math.RoundingMode.HALF_EVEN));
40	        }
41	
42	        BigDecimal taxaMensal = BigDecimal.valueOf(0.0199);
43	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);
44	        BigDecimal umMaisTaxaElevado = umMaisTaxa.pow(nParcelas);
45	
46	        BigDecimal denominador = umMaisTaxaElevado.subtract(BigDecimal.ONE);
47	        BigDecimal numerador = totalPedidoArmazenado.multiply(taxaMensal).multiply(umMaisTaxaElevado);
48	
49	        BigDecimal parcela = numerador.divide(denominador, 10, java.math.RoundingMode.HALF_EVEN);
50	        return Arredondador.arredondar(parcela);
51	    }
52	
53	    @Override
54	    public int getParcelasMaximas() {
55	        return 12;
56	    }
57	}
